import{I as o,o as l,c as r,b6 as a,J as h,w as p,j as e,a as s}from"./chunks/framework.COUcLbTA.js";const y=JSON.parse('{"title":"The Mom Test: A User Interview Method for Validating Demand","description":"A beginner-friendly introduction to The Mom Test. Learn how to avoid polite feedback, ask about real behavior and real costs, and turn “sounds good” into more reliable demand evidence.","frontmatter":{"title":"The Mom Test: A User Interview Method for Validating Demand","description":"A beginner-friendly introduction to The Mom Test. Learn how to avoid polite feedback, ask about real behavior and real costs, and turn “sounds good” into more reliable demand evidence."},"headers":[],"relativePath":"en/stage-1/appendix-mom-test/index.md","filePath":"en/stage-1/appendix-mom-test/index.md"}'),u={name:"en/stage-1/appendix-mom-test/index.md"},b=Object.assign(u,{setup(d){const i="About <strong>1.5 hours</strong>";return(c,t)=>{const n=o("ChapterIntroduction");return l(),r("div",null,[t[1]||(t[1]=a('<h1 id="the-mom-test-a-user-interview-method-for-validating-demand" tabindex="-1">The Mom Test: A User Interview Method for Validating Demand <a class="header-anchor" href="#the-mom-test-a-user-interview-method-for-validating-demand" aria-label="Permalink to “The Mom Test: A User Interview Method for Validating Demand”">​</a></h1><p><a id="top-mom"></a></p><h2 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to “Introduction”">​</a></h2>',3)),h(n,{duration:i,tags:["User Interviews","Demand Validation","User Research","Product Discovery"],coreOutput:"1 set of interview questions more likely to reveal real user information",expectedOutput:"Stop treating polite encouragement as validation and start judging direction through real behavior"},{default:p(()=>[...t[0]||(t[0]=[e("p",null,'When many beginners do product research for the first time, they assume the important thing is simply to "talk to some people." So they ask friends, classmates, coworkers, or family:',-1),e("ul",null,[e("li",null,"What do you think of this idea?"),e("li",null,"Would you use this if I built it?"),e("li",null,"Does this feature sound useful?")],-1),e("p",null,"The replies usually sound encouraging:",-1),e("ul",null,[e("li",null,"Sounds good"),e("li",null,"That seems useful"),e("li",null,"I think you should try it")],-1),e("p",null,'The problem is that these answers usually do not help you decide anything. They are often just politeness, support, or a natural instinct not to discourage you in the moment. You think you collected "market validation," but what you really collected was a pile of comforting feedback that is hard to use.',-1),e("p",null,[s("That is exactly what "),e("strong",null,"The Mom Test"),s(" is for. Its central reminder is:")],-1),e("p",null,[e("strong",null,"users are usually not trying to lie to you. The real problem is that your question format often pushes them toward nice but useless answers.")],-1)])]),_:1}),t[2]||(t[2]=a(`<div class="info custom-block"><p class="custom-block-title">Minimal SOP</p><p><strong>Goal</strong>: After this, you should be much clearer on how to talk to users without getting stuck with “sounds good,” and instead get information that actually helps you judge direction.</p><p><strong>Action</strong>: Rewrite 5 questions you would normally ask so they focus on “when did this last happen?” and “how did you handle it?”</p><p><strong>Result</strong>: You will get better at separating opinions from evidence, and encouragement from demand.</p><p><strong>Quick links</strong>: <a href="#mom-what">What The Mom Test is</a> · <a href="#mom-principles">Three core principles</a> · <a href="#mom-ai">How AI can help</a></p></div><h2 id="what-you-will-learn" tabindex="-1">What You Will Learn <a class="header-anchor" href="#what-you-will-learn" aria-label="Permalink to “What You Will Learn”">​</a></h2><ol><li>What problem The Mom Test is actually solving, and why many &quot;user interviews&quot; fail to uncover useful truth</li><li>The core principles of the method: ask less about opinions and future hypotheticals, and more about real behavior and real facts</li><li>How to rewrite low-value questions into stronger interview questions</li><li>How The Mom Test works together with JTBD, validation, and MVP decisions</li></ol><p><a id="mom-what"></a></p><h2 id="_1-what-the-mom-test-really-is" tabindex="-1"><a href="#top-mom">1. What The Mom Test Really Is</a> <a class="header-anchor" href="#_1-what-the-mom-test-really-is" aria-label="Permalink to “1. What The Mom Test Really Is”">​</a></h2><p>The Mom Test comes from Rob Fitzpatrick&#39;s book of the same name. The title sounds playful, but the point is sharp:</p><p><strong>even your mom will struggle to tell you your idea is bad if you ask the wrong way.</strong></p><p>The reason is not that she is dishonest. It is that:</p><ul><li>she does not want to hurt you</li><li>she naturally wants to encourage you</li><li>she will often answer in the direction your question already suggests</li></ul><p>And this is not only about your mom. Friends, coworkers, former classmates, and even strangers often do the same thing when they react to a product idea. A positive answer does not necessarily mean the demand is real. It may simply mean you asked in a way that made a flattering answer easy.</p><p>So the point of The Mom Test is not really &quot;do not ask your mom.&quot; It is:</p><p><strong>do not ask in a way that makes almost anyone answer by encouraging you.</strong></p><p>What this method really teaches is how to use conversation to get closer to real demand instead of collecting feel-good commentary.</p><h2 id="_2-the-core-problem-it-solves" tabindex="-1">2. The Core Problem It Solves <a class="header-anchor" href="#_2-the-core-problem-it-solves" aria-label="Permalink to “2. The Core Problem It Solves”">​</a></h2><p>The Mom Test mainly helps you avoid one very common cognitive mistake:</p><p><strong>mistaking polite positive feedback for real demand.</strong></p><p>For example, people often ask:</p><ul><li>What do you think of this app idea?</li><li>If I built an AI tool that rewrites resumes, would you use it?</li><li>Does this feature sound valuable?</li></ul><p>These questions have three things in common:</p><ul><li>they ask for opinions</li><li>they contain some amount of suggestion or framing</li><li>they talk about a future that has not happened yet</li></ul><p>People are usually unreliable when answering about opinion and imagined future behavior. They tend to overestimate their own interest, their own follow-through, and their own willingness to pay.</p><p>That is why The Mom Test keeps reminding you:</p><ul><li>do not trust praise for your idea too quickly</li><li>do not trust predictions about future behavior too quickly</li><li>bring the conversation back to what the user has already done in real life</li></ul><p>Compared with &quot;Would you use this?&quot;, a question like &quot;How did you handle this last time?&quot; is usually much closer to truth.</p><p><a id="mom-principles"></a></p><h2 id="_3-three-core-principles" tabindex="-1"><a href="#top-mom">3. Three Core Principles</a> <a class="header-anchor" href="#_3-three-core-principles" aria-label="Permalink to “3. Three Core Principles”">​</a></h2><p>If you want to remember only the most important part first, remember these three principles.</p><h3 id="_3-1-talk-less-about-your-idea-and-more-about-the-user-s-real-past-experience" tabindex="-1">3.1 Talk less about your idea and more about the user&#39;s real past experience <a class="header-anchor" href="#_3-1-talk-less-about-your-idea-and-more-about-the-user-s-real-past-experience" aria-label="Permalink to “3.1 Talk less about your idea and more about the user&#39;s real past experience”">​</a></h3><p>Many weak interviews start with too much explanation: your solution, your excitement, your product concept, your feature plan. Once you do that, the other person often shifts into &quot;supportive mode.&quot;</p><p>A better direction is to center the conversation on their real experience:</p><ul><li>When was the last time this happened?</li><li>What were you doing at the time?</li><li>How did you handle it?</li><li>Which step felt the most annoying?</li></ul><p>Questions like these pull the conversation back into reality instead of keeping it in imagined preference.</p><h3 id="_3-2-ask-less-about-abstract-opinions-and-more-about-concrete-facts" tabindex="-1">3.2 Ask less about abstract opinions and more about concrete facts <a class="header-anchor" href="#_3-2-ask-less-about-abstract-opinions-and-more-about-concrete-facts" aria-label="Permalink to “3.2 Ask less about abstract opinions and more about concrete facts”">​</a></h3><p>&quot;That sounds useful,&quot; &quot;Seems nice,&quot; and &quot;I think I would like that&quot; are all too abstract to guide product decisions.</p><p>Higher-value information usually looks more like this:</p><ul><li>I spent two hours dealing with this last week</li><li>Right now I am holding it together with Excel and chat</li><li>I already paid for something related to this last month</li><li>My biggest fear is not slowness, it is making a mistake</li></ul><p>That kind of information helps you judge the intensity of the problem, how often it happens, and whether anyone might pay to solve it.</p><h3 id="_3-3-ask-less-about-the-user-s-preferred-solution-and-pay-more-attention-to-how-they-solve-the-problem-today" tabindex="-1">3.3 Ask less about the user&#39;s preferred solution and pay more attention to how they solve the problem today <a class="header-anchor" href="#_3-3-ask-less-about-the-user-s-preferred-solution-and-pay-more-attention-to-how-they-solve-the-problem-today" aria-label="Permalink to “3.3 Ask less about the user&#39;s preferred solution and pay more attention to how they solve the problem today”">​</a></h3><p>Users are often good at describing pain, but not always good at designing the best product.</p><p>If you ask:</p><ul><li>Would you want an AI to do this automatically?</li><li>Would a smart feature help?</li></ul><p>you usually get a vague opinion about a proposed solution, not evidence about the underlying need.</p><p>Better questions are:</p><ul><li>What do you do today?</li><li>Why do you do it that way?</li><li>What is bad about that method?</li></ul><p>Seeing the current workaround clearly is often more valuable than asking &quot;What do you want us to build?&quot;</p><h2 id="_4-why-people-keep-giving-nice-but-unhelpful-answers" tabindex="-1">4. Why People Keep Giving Nice but Unhelpful Answers <a class="header-anchor" href="#_4-why-people-keep-giving-nice-but-unhelpful-answers" aria-label="Permalink to “4. Why People Keep Giving Nice but Unhelpful Answers”">​</a></h2><p>If you understand this part, you will make fewer mistakes during interviews.</p><h3 id="_4-1-people-naturally-try-to-be-polite" tabindex="-1">4.1 People naturally try to be polite <a class="header-anchor" href="#_4-1-people-naturally-try-to-be-polite" aria-label="Permalink to “4.1 People naturally try to be polite”">​</a></h3><p>Especially when the person knows you, it is hard for them to say:</p><ul><li>this direction does not sound very strong</li><li>I would never use this</li><li>this is not important enough for me</li></ul><p>They are much more likely to say something like &quot;sounds interesting&quot; or &quot;could be useful.&quot;</p><h3 id="_4-2-people-overestimate-their-future-selves" tabindex="-1">4.2 People overestimate their future selves <a class="header-anchor" href="#_4-2-people-overestimate-their-future-selves" aria-label="Permalink to “4.2 People overestimate their future selves”">​</a></h3><p>Many people honestly believe their future self will:</p><ul><li>be more disciplined</li><li>be more willing to learn</li><li>be more willing to pay</li><li>be more willing to try new tools</li></ul><p>So the sentence &quot;I would probably use that&quot; often does not mean they really will.</p><h3 id="_4-3-your-question-format-is-already-shaping-the-answer" tabindex="-1">4.3 Your question format is already shaping the answer <a class="header-anchor" href="#_4-3-your-question-format-is-already-shaping-the-answer" aria-label="Permalink to “4.3 Your question format is already shaping the answer”">​</a></h3><p>When you ask:</p><ul><li>My idea sounds pretty good, right?</li><li>This feature would help you, right?</li></ul><p>you are already hiding the &quot;good answer&quot; inside the question.</p><p>That is one reason The Mom Test strongly warns you:</p><p><strong>do not turn the interview into a search for reassurance.</strong></p><h2 id="_5-weak-questions-vs-better-questions" tabindex="-1">5. Weak Questions vs Better Questions <a class="header-anchor" href="#_5-weak-questions-vs-better-questions" aria-label="Permalink to “5. Weak Questions vs Better Questions”">​</a></h2><p>These comparisons are useful because almost every beginner asks some version of them.</p><table tabindex="0"><thead><tr><th>Weak question</th><th>Better question</th></tr></thead><tbody><tr><td>What do you think of this idea?</td><td>When was the last time this happened to you?</td></tr><tr><td>Would you use this if it existed?</td><td>How do you handle this now?</td></tr><tr><td>Would you pay for this?</td><td>Have you already spent time or money on this problem? What did you spend it on?</td></tr><tr><td>Is this feature important?</td><td>Which step in the process feels slowest, most frustrating, or least trustworthy?</td></tr><tr><td>Would you want an AI to do this automatically?</td><td>Why have you not found a better workaround yet?</td></tr></tbody></table><p>The most important thing in the table is not the wording itself, but the direction of the shift:</p><ul><li>from opinion to fact</li><li>from future to past</li><li>from your solution to the user&#39;s problem</li></ul><h2 id="_6-a-simple-interview-flow-you-can-use-right-away" tabindex="-1">6. A Simple Interview Flow You Can Use Right Away <a class="header-anchor" href="#_6-a-simple-interview-flow-you-can-use-right-away" aria-label="Permalink to “6. A Simple Interview Flow You Can Use Right Away”">​</a></h2><p>If you want to talk to someone now, you can use this order directly.</p><h3 id="_6-1-open-as-a-learner-not-a-seller" tabindex="-1">6.1 Open as a learner, not a seller <a class="header-anchor" href="#_6-1-open-as-a-learner-not-a-seller" aria-label="Permalink to “6.1 Open as a learner, not a seller”">​</a></h3><p>For example:</p><blockquote><p>I am trying to understand how people actually deal with this in real life. I am not selling anything right now.</p></blockquote><p>That makes it easier for the other person to drop the instinct to encourage you.</p><h3 id="_6-2-start-from-the-last-real-incident" tabindex="-1">6.2 Start from the last real incident <a class="header-anchor" href="#_6-2-start-from-the-last-real-incident" aria-label="Permalink to “6.2 Start from the last real incident”">​</a></h3><p>Good opening questions are:</p><ul><li>When was the last time this happened?</li><li>What happened?</li><li>What did you do first?</li></ul><p>Once the conversation enters one specific real event, the quality of the information usually improves a lot.</p><h3 id="_6-3-then-ask-about-behavior-cost-and-alternatives" tabindex="-1">6.3 Then ask about behavior, cost, and alternatives <a class="header-anchor" href="#_6-3-then-ask-about-behavior-cost-and-alternatives" aria-label="Permalink to “6.3 Then ask about behavior, cost, and alternatives”">​</a></h3><p>Continue with questions like:</p><ul><li>What do you do today?</li><li>What feels worst about that method?</li><li>How much time, money, or energy does it cost?</li><li>Have you tried anything else? Why did you stop?</li></ul><h3 id="_6-4-only-then-judge-pain-and-priority" tabindex="-1">6.4 Only then judge pain and priority <a class="header-anchor" href="#_6-4-only-then-judge-pain-and-priority" aria-label="Permalink to “6.4 Only then judge pain and priority”">​</a></h3><p>You do not have to ask directly, &quot;How painful is this?&quot; You can often judge it from the details:</p><ul><li>does this happen often?</li><li>are they already actively patching the problem?</li><li>have they already paid some real cost?</li><li>do they talk about it with visible frustration or emotion?</li></ul><p>Those clues are much more useful than asking, &quot;Is this a pain point for you?&quot;</p><h2 id="_7-a-more-complete-example" tabindex="-1">7. A More Complete Example <a class="header-anchor" href="#_7-a-more-complete-example" aria-label="Permalink to “7. A More Complete Example”">​</a></h2><p>Suppose you want to build an AI product that helps college students improve resumes.</p><h3 id="weak-questions" tabindex="-1">Weak questions <a class="header-anchor" href="#weak-questions" aria-label="Permalink to “Weak questions”">​</a></h3><p>You ask a classmate:</p><blockquote><p>I want to build an AI resume optimizer. What do you think?<br> If it could automatically rewrite your resume for a job description, would you use it?</p></blockquote><p>They will probably say:</p><ul><li>sounds good</li><li>I think that could be useful</li><li>I would try it if it were free</li></ul><p>Those answers give you almost no reliable signal about the actual strength of the demand.</p><h3 id="better-questions" tabindex="-1">Better questions <a class="header-anchor" href="#better-questions" aria-label="Permalink to “Better questions”">​</a></h3><p>You can change the conversation to this:</p><blockquote><p>When was the last time you edited your resume?<br> Why did you need to change it?<br> How did you do it?<br> Which step felt hardest?<br> Did you ask anyone else to review it?<br> Have you ever spent money or a lot of time on this?</p></blockquote><p>From these questions, you may learn things like:</p><ul><li>many people are not bad at writing, but bad at tailoring the resume for different roles</li><li>the biggest pain is often not formatting, but not knowing which experience belongs</li><li>they delay not because they are lazy, but because every revision round drains them</li><li>current workarounds already include seniors, templates, AI tools, and friends</li></ul><p>That gets you much closer to the real problem.</p><h2 id="_8-how-the-mom-test-works-with-jtbd" tabindex="-1">8. How The Mom Test Works with JTBD <a class="header-anchor" href="#_8-how-the-mom-test-works-with-jtbd" aria-label="Permalink to “8. How The Mom Test Works with JTBD”">​</a></h2><p>If JTBD helps you see what kind of progress the user is trying to make, The Mom Test teaches you:</p><p><strong>how to verify through interviews whether that job is actually real.</strong></p><p>You can combine the two like this:</p><ol><li>use JTBD to draft one job hypothesis</li><li>use The Mom Test style questions to ask about the last real situation</li><li>judge whether that job is frequent, painful, and worth prioritizing</li></ol><p>Example JTBD hypothesis:</p><blockquote><p>When I am preparing internship applications, I want to adapt my old resume into a role-specific version so I can submit faster.</p></blockquote><p>Now validate it with questions like:</p><ul><li>When was your last internship application?</li><li>How did you edit your resume?</li><li>Which part was hardest to rewrite?</li><li>How did you judge whether it was ready?</li></ul><p>That is how the two methods connect:</p><ul><li>JTBD helps define the need hypothesis</li><li>The Mom Test helps validate it through conversation</li></ul><h2 id="_9-common-beginner-mistakes-in-interviews" tabindex="-1">9. Common Beginner Mistakes in Interviews <a class="header-anchor" href="#_9-common-beginner-mistakes-in-interviews" aria-label="Permalink to “9. Common Beginner Mistakes in Interviews”">​</a></h2><h3 id="_9-1-turning-the-interview-into-a-product-presentation" tabindex="-1">9.1 Turning the interview into a product presentation <a class="header-anchor" href="#_9-1-turning-the-interview-into-a-product-presentation" aria-label="Permalink to “9.1 Turning the interview into a product presentation”">​</a></h3><p>If you explain too much about your idea, the other person starts helping you instead of telling you the truth.</p><h3 id="_9-2-interviewing-only-friends" tabindex="-1">9.2 Interviewing only friends <a class="header-anchor" href="#_9-2-interviewing-only-friends" aria-label="Permalink to “9.2 Interviewing only friends”">​</a></h3><p>Friends are not useless, but they are more likely to encourage you. You need at least some people who are closer to real users and less emotionally invested in you.</p><h3 id="_9-3-asking-about-features-too-early" tabindex="-1">9.3 Asking about features too early <a class="header-anchor" href="#_9-3-asking-about-features-too-early" aria-label="Permalink to “9.3 Asking about features too early”">​</a></h3><p>If the problem is still unclear, detailed feature questions usually mean you are moving into solution mode too early.</p><h3 id="_9-4-treating-i-would-use-it-as-validation" tabindex="-1">9.4 Treating &quot;I would use it&quot; as validation <a class="header-anchor" href="#_9-4-treating-i-would-use-it-as-validation" aria-label="Permalink to “9.4 Treating &quot;I would use it&quot; as validation”">​</a></h3><p>Interviews can help you judge direction, but interviews are not the whole validation step. Real validation still depends on real cost: time, switching effort, trial behavior, or payment.</p><h3 id="_9-5-not-organizing-what-you-learned" tabindex="-1">9.5 Not organizing what you learned <a class="header-anchor" href="#_9-5-not-organizing-what-you-learned" aria-label="Permalink to “9.5 Not organizing what you learned”">​</a></h3><p>If you do not organize the conversation afterward, it quickly becomes a blurry impression. Try to capture:</p><ul><li>repeated problems</li><li>emotional words in the user&#39;s own phrasing</li><li>current workarounds</li><li>costs already paid</li><li>your updated judgment</li></ul><h2 id="_10-a-reusable-question-checklist" tabindex="-1">10. A Reusable Question Checklist <a class="header-anchor" href="#_10-a-reusable-question-checklist" aria-label="Permalink to “10. A Reusable Question Checklist”">​</a></h2><p>If you want to start quickly, this set is broad enough for many interviews.</p><h3 id="opening-questions" tabindex="-1">Opening questions <a class="header-anchor" href="#opening-questions" aria-label="Permalink to “Opening questions”">​</a></h3><ul><li>When was the last time this problem happened?</li><li>What exactly happened?</li></ul><h3 id="behavior-questions" tabindex="-1">Behavior questions <a class="header-anchor" href="#behavior-questions" aria-label="Permalink to “Behavior questions”">​</a></h3><ul><li>How did you handle it?</li><li>Why did you do it that way?</li></ul><h3 id="cost-questions" tabindex="-1">Cost questions <a class="header-anchor" href="#cost-questions" aria-label="Permalink to “Cost questions”">​</a></h3><ul><li>How much time or energy does this usually cost?</li><li>Have you ever spent money to solve it?</li></ul><h3 id="alternative-questions" tabindex="-1">Alternative questions <a class="header-anchor" href="#alternative-questions" aria-label="Permalink to “Alternative questions”">​</a></h3><ul><li>What other tools or methods have you tried?</li><li>Why did you stop using them?</li></ul><h3 id="closing-question" tabindex="-1">Closing question <a class="header-anchor" href="#closing-question" aria-label="Permalink to “Closing question”">​</a></h3><ul><li>If this problem came up again, what would an ideal solution feel like?</li></ul><p>This is fine near the end, but it should not come first. Earlier in the conversation, you want facts more than wishes.</p><h2 id="_11-summary" tabindex="-1">11. Summary <a class="header-anchor" href="#_11-summary" aria-label="Permalink to “11. Summary”">​</a></h2><p>The most important contribution of The Mom Test is not a set of &quot;better conversation tricks.&quot; It is a more sober way to judge what you hear:</p><ul><li>do not trust praise for your idea too quickly</li><li>do not treat &quot;I would use that&quot; as real demand</li><li>do not turn interviews into a search for approval</li></ul><p>The most useful conversations usually keep coming back to:</p><ul><li>the user&#39;s most recent real experience</li><li>how they handle the problem today</li><li>what cost they have already paid</li><li>where they feel obvious discomfort</li></ul><p>When you start asking in this way, the answers may sound less flattering, but they are usually much more useful.</p><p><strong>In product work, useful truth is always better than encouraging noise.</strong></p><p><a id="mom-ai"></a></p><h2 id="_12-how-ai-can-help-with-interviews" tabindex="-1"><a href="#top-mom">12. How AI Can Help with Interviews</a> <a class="header-anchor" href="#_12-how-ai-can-help-with-interviews" aria-label="Permalink to “12. How AI Can Help with Interviews”">​</a></h2><p>The Mom Test is still a method for talking to real people, so AI cannot replace real interviews. But AI is extremely useful before, during, and after interviews, especially for beginners who need structure.</p><h3 id="_12-1-rewrite-weak-questions" tabindex="-1">12.1 Rewrite weak questions <a class="header-anchor" href="#_12-1-rewrite-weak-questions" aria-label="Permalink to “12.1 Rewrite weak questions”">​</a></h3><p>Many people know they should not ask, &quot;What do you think of my idea?&quot;, but they still drift back to that kind of wording. You can ask AI to rewrite your draft questions first:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Below are the questions I plan to ask in user interviews:</span></span>
<span class="line"><span>[paste your questions]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please rewrite them using The Mom Test principles:</span></span>
<span class="line"><span>1. remove opinion-based questions</span></span>
<span class="line"><span>2. remove future hypothetical questions</span></span>
<span class="line"><span>3. turn them into questions about real past behavior, current alternatives, and real costs</span></span>
<span class="line"><span>4. organize the result into 8-10 interview questions I can actually use</span></span></code></pre></div><p>A very beginner-style input also works:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want to ask users:</span></span>
<span class="line"><span>1. What do you think of my AI resume tool?</span></span>
<span class="line"><span>2. Would you use it?</span></span>
<span class="line"><span>3. Would you pay for it?</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please turn these into better interview questions.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Rewritten questions:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. When was the last time you edited your resume?</span></span>
<span class="line"><span>2. Why did you need to edit it?</span></span>
<span class="line"><span>3. How did you do it?</span></span>
<span class="line"><span>4. Which part took the most time?</span></span>
<span class="line"><span>5. Did you ask anyone else to review it?</span></span>
<span class="line"><span>6. Have you ever spent money or a lot of time solving this?</span></span></code></pre></div><p>That output is useful because it turns opinion-seeking questions into behavior-seeking questions.</p><h3 id="_12-2-create-different-interview-guides-for-different-user-types" tabindex="-1">12.2 Create different interview guides for different user types <a class="header-anchor" href="#_12-2-create-different-interview-guides-for-different-user-types" aria-label="Permalink to “12.2 Create different interview guides for different user types”">​</a></h3><p>The same problem feels different to different user groups. Students, HR people, and senior peers often care about different parts of the workflow. AI can generate separate interview guides for each group.</p><p>For example:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>I want to talk to two groups:</span></span>
<span class="line"><span>1. college students applying for internships for the first time</span></span>
<span class="line"><span>2. seniors who have reviewed many resumes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please create a 6-question interview guide for each group.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>For students:</span></span>
<span class="line"><span>1. When was your last internship application?</span></span>
<span class="line"><span>2. What part felt hardest?</span></span>
<span class="line"><span>3. How do you judge whether your resume is ready?</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>For seniors:</span></span>
<span class="line"><span>1. When did you last review a junior&#39;s resume?</span></span>
<span class="line"><span>2. What common issues do you see most often?</span></span>
<span class="line"><span>3. Where do students usually get stuck?</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>That makes interview prep much easier because you do not need to invent every question from scratch.</p><h3 id="_12-3-sort-interview-notes-into-facts-vs-opinions" tabindex="-1">12.3 Sort interview notes into facts vs opinions <a class="header-anchor" href="#_12-3-sort-interview-notes-into-facts-vs-opinions" aria-label="Permalink to “12.3 Sort interview notes into facts vs opinions”">​</a></h3><p>After interviews, the problem is often not &quot;too little information,&quot; but &quot;too much scattered information.&quot; AI is good at turning messy notes into structured evidence:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Below are notes from 3 user interviews.</span></span>
<span class="line"><span>Please organize them using The Mom Test:</span></span>
<span class="line"><span>1. which parts are facts and which are opinions</span></span>
<span class="line"><span>2. what the user&#39;s last real behavior was</span></span>
<span class="line"><span>3. what the current workaround is</span></span>
<span class="line"><span>4. what time, money, or effort cost they have already paid</span></span>
<span class="line"><span>5. which problems show up repeatedly</span></span>
<span class="line"><span>6. which statements sound positive but have weak evidence</span></span></code></pre></div><p>Simple beginner input:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Here are my notes from one interview:</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- she said she would probably try such a tool</span></span>
<span class="line"><span>- last week she spent one full evening editing her resume</span></span>
<span class="line"><span>- she currently asks friends for feedback</span></span>
<span class="line"><span>- she is not sure when a resume is &quot;good enough&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Please separate facts from opinions.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Opinion:</span></span>
<span class="line"><span>- she would probably try such a tool</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Facts:</span></span>
<span class="line"><span>- she spent one full evening editing her resume</span></span>
<span class="line"><span>- she currently depends on friends for feedback</span></span>
<span class="line"><span>- she is not sure when the resume is good enough</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Useful evidence:</span></span>
<span class="line"><span>- the problem happened recently</span></span>
<span class="line"><span>- she already paid a meaningful time cost</span></span>
<span class="line"><span>- the current workaround depends on other people</span></span></code></pre></div><p>This is especially useful because it helps beginners separate &quot;sounds nice&quot; from &quot;supports a real decision.&quot;</p><h3 id="_12-4-do-a-light-web-search-before-interviews" tabindex="-1">12.4 Do a light web search before interviews <a class="header-anchor" href="#_12-4-do-a-light-web-search-before-interviews" aria-label="Permalink to “12.4 Do a light web search before interviews”">​</a></h3><p>Before interviews even begin, AI can help with a light external scan:</p><ul><li>how people complain about the problem in public communities</li><li>which tools get criticized most often</li><li>whether people already spend money on related solutions</li><li>what alternatives already exist</li></ul><p>Example prompt:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Please look up:</span></span>
<span class="line"><span>&quot;What do students complain about most when editing resumes?&quot;</span></span>
<span class="line"><span>Summarize the 5 most common complaints in simple language.</span></span></code></pre></div><p>Possible AI output:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Common complaints:</span></span>
<span class="line"><span>1. I don&#39;t know what belongs on the resume</span></span>
<span class="line"><span>2. I have to rewrite it for every role and it is exhausting</span></span>
<span class="line"><span>3. I keep editing but still do not know if it is good enough</span></span>
<span class="line"><span>4. I do not have reliable feedback</span></span>
<span class="line"><span>5. I keep delaying because I never feel ready</span></span></code></pre></div><p>This does not replace real interviews, but it helps you enter them with a better starting map.</p><h3 id="_12-5-ask-ai-to-review-your-interview-technique" tabindex="-1">12.5 Ask AI to review your interview technique <a class="header-anchor" href="#_12-5-ask-ai-to-review-your-interview-technique" aria-label="Permalink to “12.5 Ask AI to review your interview technique”">​</a></h3><p>You can also paste one interview transcript and ask AI to critique your questioning:</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Here is a transcript from one user interview.</span></span>
<span class="line"><span>Please review it using The Mom Test:</span></span>
<span class="line"><span>1. Which questions sound like I was seeking reassurance?</span></span>
<span class="line"><span>2. Which questions were leading?</span></span>
<span class="line"><span>3. Where should I have asked more about facts?</span></span>
<span class="line"><span>4. How could I ask this better next time?</span></span></code></pre></div><p>That is especially helpful for beginners because it trains the instinct to ask:</p><p><strong>am I collecting evidence, or am I just collecting encouragement?</strong></p><h2 id="assignments" tabindex="-1">Assignments <a class="header-anchor" href="#assignments" aria-label="Permalink to “Assignments”">​</a></h2><ol><li>Write 5 weak interview questions you might normally ask</li><li>Rewrite them in The Mom Test style</li><li>Interview 3 potential users about the last time the problem happened</li><li>Sort your notes into facts, workarounds, costs, and repeated pain points</li></ol><h2 id="further-reading" tabindex="-1">Further Reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to “Further Reading”">​</a></h2><ul><li><a href="https://momtestbook.com/" target="_blank" rel="noreferrer">The Mom Test official site</a></li><li><a href="https://www.robfitz.com/the-mom-test/" target="_blank" rel="noreferrer">Rob Fitzpatrick: The Mom Test</a></li></ul>`,183))])}}});export{y as __pageData,b as default};
